def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = 7
    seen = set()

    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            color = g[r][c]
            stack = [(r, c)]
            cells = []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and g[ny][nx] == color:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            top, bottom, left, right = min(ys), max(ys), min(xs), max(xs)
            cellset = set(cells)
            border = {(y, x) for y in range(top, bottom + 1) for x in range(left, right + 1)
                      if y in (top, bottom) or x in (left, right)}
            interior = {(y, x) for y in range(top + 1, bottom) for x in range(left + 1, right)}
            if cellset == border and interior and all(g[y][x] == bg for y, x in interior):
                for y, x in ((top - 1, left), (top - 1, right), (bottom + 1, left),
                             (bottom + 1, right), (top, left - 1), (top, right + 1),
                             (bottom, left - 1), (bottom, right + 1)):
                    if 0 <= y < h and 0 <= x < w:
                        g[y][x] = 2
    return g
